def reward(context, completion):
    # Define a simple reward based on the presence of the keyword 'hello'
    if 'hello' in completion.lower():
        return 10
    else:
        return -1

def reward(context, completion):
    # Calculate reward based on the length of the completion
    length_reward = len(completion)

    # Calculate reward based on the presence of key information from the context
    info_reward = 0
    for key in context:
        if key in completion:
            info_reward += 100

    # Total reward is the sum of length and information rewards
    total_reward = length_reward + info_reward
    return max(min(total_reward, 100000), -100000)

def reward(context, completion):
    # Reward based on the presence of specific keywords indicating quality
    quality_keywords = ['elegant', 'efficient', 'insightful', 'clear', 'concise']
    reward_value = 0
    for keyword in quality_keywords:
        if keyword in completion.lower():
            reward_value += 10000  # Reward for each quality keyword found
    return min(reward_value, 100000)

def reward(context, completion):
    # If the completion is empty, give a negative reward
    if not completion:
        return -100000
    # Encourage completion length
    length_reward = len(completion) * 0.1
    # Ensure we don't exceed the max reward
    if length_reward > 100000:
        return 100000
    return length_reward

